package com.nextrade.engine.risk; public final class MaxOpenOrdersRule implements RiskRule { private final int max; public MaxOpenOrdersRule(int max){this.max=max;} public RiskDecision evaluate(RiskContext context){return context.openOrderCount()<=max?RiskDecision.allow():RiskDecision.block("MAX_OPEN_ORDERS","Open order limit exceeded");} public String name(){return "MAX_OPEN_ORDERS";} }